from collections import Counter

class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        def key(a, b):
            g = gcd(a, b)
            return (a // g, b // g)
        ans = 0
        for q in range(1, n):
            L = Counter()
            for p in range(0, q - 1):
                L[key(nums[p], nums[q])] += 1
            if not L:
                continue
            for r in range(q + 2, n):
                R = Counter()
                for s in range(r + 2, n):
                    R[key(nums[s], nums[r])] += 1
                for k, c in R.items():
                    if k in L:
                        ans += c * L[k]
        return ans
