class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        counter = defaultdict(int)
        ans = 0
        for r in range(4, n):
            q = r - 2
            # add pairs (p, q) with p <= q-2
            for p in range(0, q - 1):
                a, b = nums[p], nums[q]
                g = gcd(a, b)
                counter[(a // g, b // g)] += 1
            # process s >= r+2 with pair (r, s)
            for s in range(r + 2, n):
                a, b = nums[s], nums[r]
                g = gcd(a, b)
                ans += counter.get((a // g, b // g), 0)
        return ans
