class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)

        def frac(a, b):
            g = gcd(a, b)
            return (a // g, b // g)

        # right[r]: dict of fraction nums[s]/nums[r] counts for s >= r+2
        right = [None] * n
        cnt = {}
        for r in range(n - 1, -1, -1):
            # cnt holds values for s >= r+2
            d = {}
            for v, c in cnt.items():
                k = frac(v, nums[r])
                d[k] = d.get(k, 0) + c
            right[r] = d
            # add s = r+1 for next iteration (r-1 needs s >= r+1)
            if r + 1 < n:
                cnt[nums[r + 1]] = cnt.get(nums[r + 1], 0) + 1

        total = 0
        for q in range(n):
            if q < 2:
                continue
            # left counts: p in [0, q-2], fraction nums[p]/nums[q]
            L = {}
            cl = {}
            for p in range(q - 1):
                cl[nums[p]] = cl.get(nums[p], 0) + 1
            for v, c in cl.items():
                k = frac(v, nums[q])
                L[k] = L.get(k, 0) + c
            if not L:
                continue
            for r in range(q + 2, n):
                R = right[r]
                if not R:
                    continue
                if len(L) <= len(R):
                    for k, c in L.items():
                        x = R.get(k)
                        if x:
                            total += c * x
                else:
                    for k, c in R.items():
                        x = L.get(k)
                        if x:
                            total += c * x
        return total
