        # Rdict[r]: counts of frac(nums[s], nums[r]) for s >= r+2
        Rdict = [None] * n
        cur = {}
        for r in range(n - 1, -1, -1):
            # cur contains s >= r+2
            Rdict[r] = cur
            # add s = r+1 for next iteration (r-1 needs s >= r+1)
            # next r' = r-1 needs s >= r+1; so add index r+1 if valid
            if r + 1 < n:
                f = frac(nums[r + 1], nums[r])
                cur = dict(cur)
                cur[f] = cur.get(f, 0) + 1
        # Note: copying cur above; Rdict[r] refers to the state before adding r+1-based entries.

        total = 0
        for q in range(2, n):
            # L: counts of frac(nums[p], nums[q]) for p <= q-2
            L = [frac(nums[p], nums[q]) for p in range(q - 1)]
            for r in range(q + 2, n):
                D = Rdict[r]
                if not D:
                    continue
                cnt = 0
                for f in L:
                    v = D.get(f)
                    if v:
                        cnt += v
                total += cnt
        return total
