class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        # suf[i][v] = count of value v in nums[i:]
        suf = [None] * (n + 2)
        cur = Counter()
        suf[n] = {}
        suf[n + 1] = {}
        for i in range(n - 1, -1, -1):
            cur[nums[i]] += 1
            suf[i] = dict(cur)
        ans = 0
        for q in range(2, n - 2):
            left = Counter()
            for p in range(q - 1):
                left[nums[p]] += 1
            for r in range(q + 2, n - 2):
                start = r + 2
                sd = suf[start]
                nq = nums[q]
                nr = nums[r]
                for v, c in left.items():
                    need = v * nr
                    if need % nq == 0:
                        t = need // nq
                        ans += c * sd.get(t, 0)
        return ans
