        n = len(nums)
        # Suf[r]: counts of reduced nums[s]/nums[r] for s >= r+2
        Suf = [None] * n
        for r in range(n):
            d = defaultdict(int)
            for s in range(r + 2, n):
                g = gcd(nums[s], nums[r])
                d[(nums[s] // g, nums[r] // g)] += 1
            Suf[r] = d
        total = 0
        for q in range(2, n):
            L = defaultdict(int)
            for p in range(q - 1):
                g = gcd(nums[p], nums[q])
                L[(nums[p] // g, nums[q] // g)] += 1
            # r from q+2
            for r in range(q + 2, n):
                S = Suf[r]
                if len(L) < len(S):
                    for k, c in L.items():
                        total += c * S.get(k, 0)
                else:
                    for k, c in S.items():
                        total += c * L.get(k, 0)
        return total
