class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        C = {}
        for r in range(4, n):
            # add pairs (p, q) with q = r - 2, p <= q - 2
            q = r - 2
            if q >= 2:
                for p in range(q - 1):
                    a, b = nums[p], nums[q]
                    g = gcd(a, b)
                    key = (a // g, b // g)
                    C[key] = C.get(key, 0) + 1
            # count s >= r+2 with nums[s]/nums[r] matching
            # need nums[p]/nums[q] == nums[s]/nums[r]
            if r + 2 < n:
                for s in range(r + 2, n):
                    a, b = nums[s], nums[r]
                    g = gcd(a, b)
                    key = (a // g, b // g)
                    if key in C:
                        ans += C[key]
        return ans

